#!/usr/bin/env node
// Copies the third-party browser files MetaCode's pages use into public/vendor/, so the app works with
// no internet and no CDN: the same pinned versions the pages loaded from jsDelivr and Google Fonts before.
//
//   node scripts/vendor-web.js           rebuilds public/vendor/ (and public/css/fonts.css)
//   node scripts/vendor-web.js --check   only checks that public/vendor/ matches VENDOR.json
//
// Packages come from the npm registry through `npm pack`, which verifies each tarball against the
// registry's integrity hash. Only the files the pages load are kept, with each package's licence, and
// public/vendor/VENDOR.json records the version, the tarball's integrity and every file's sha256.
'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'public', 'vendor');
const FONTS_CSS = path.join(ROOT, 'public', 'css', 'fonts.css');

// [from (in the package), to (under public/vendor/)]. "strip-map": drop the sourceMappingURL comment
// (the .map files aren't shipped)
const PACKAGES = [
  { spec: 'papaparse@5.4.1', dir: 'papaparse', files: [['papaparse.min.js', 'papaparse.min.js']], license: 'LICENSE' },
  { spec: 'chart.js@4.4.0', dir: 'chart.js', files: [['dist/chart.umd.js', 'chart.umd.js', 'strip-map']], license: 'LICENSE.md' },
  { spec: 'd3@7.8.5', dir: 'd3', files: [['dist/d3.min.js', 'd3.min.js']], license: 'LICENSE' },
  { spec: '@highlightjs/cdn-assets@11.9.0', dir: 'highlight', files: [['highlight.min.js', 'highlight.min.js'], ['styles/github-dark.min.css', 'github-dark.min.css']], license: 'LICENSE' },
  // CodeMirror 5, for the Scraper's custom-code editor (the AI Lab uses CodeMirror 6 from node_modules)
  { spec: 'codemirror@5.65.21', dir: 'codemirror5', license: 'LICENSE', files: [
    ['lib/codemirror.js', 'lib/codemirror.js'], ['lib/codemirror.css', 'lib/codemirror.css'],
    ['mode/javascript/javascript.js', 'mode/javascript/javascript.js'], ['mode/python/python.js', 'mode/python/python.js'],
    ['addon/edit/matchbrackets.js', 'addon/edit/matchbrackets.js'], ['addon/edit/closebrackets.js', 'addon/edit/closebrackets.js'],
  ] },
];
// The UI fonts, as variable fonts (one file covers every weight): Latin and Latin Extended only
const FONTS = [
  { spec: '@fontsource-variable/space-grotesk@5.3.0', family: 'Space Grotesk', file: 'space-grotesk' },
  { spec: '@fontsource-variable/inter@5.3.0', family: 'Inter', file: 'inter' },
  { spec: '@fontsource-variable/jetbrains-mono@5.3.0', family: 'JetBrains Mono', file: 'jetbrains-mono' },
];
const SUBSETS = ['latin-ext', 'latin'];

const sha256 = buf => crypto.createHash('sha256').update(buf).digest('hex');
const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';

function pack(spec, tmp) {
  const out = execFileSync(npm, ['pack', spec, '--json', '--pack-destination', tmp], { cwd: tmp, encoding: 'utf8', shell: process.platform === 'win32' });
  const info = JSON.parse(out)[0];
  const dir = path.join(tmp, info.filename.replace(/\.tgz$/, ''));
  fs.mkdirSync(dir, { recursive: true });
  execFileSync('tar', ['-xzf', path.join(tmp, info.filename), '-C', dir]);
  return { root: path.join(dir, 'package'), version: info.version, integrity: info.integrity };
}

function write(rel, buf, record) {
  const to = path.join(OUT, rel);
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.writeFileSync(to, buf);
  record.files.push({ path: 'vendor/' + rel.split(path.sep).join('/'), bytes: buf.length, sha256: sha256(buf) });
}

function build() {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'metacode-vendor-'));
  try {
    fs.rmSync(OUT, { recursive: true, force: true });
    const manifest = { note: 'Generated by scripts/vendor-web.js: do not edit by hand.', packages: [] };
    for (const p of PACKAGES) {
      const pkg = pack(p.spec, tmp);
      const record = { name: p.spec.replace(/@[^@]+$/, ''), version: pkg.version, integrity: pkg.integrity, files: [] };
      for (const [from, to, how] of p.files) {
        let buf = fs.readFileSync(path.join(pkg.root, from));
        if (how === 'strip-map') buf = Buffer.from(buf.toString('utf8').replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n'));
        write(path.join(p.dir, to), buf, record);
      }
      write(path.join(p.dir, 'LICENSE'), fs.readFileSync(path.join(pkg.root, p.license)), record);
      manifest.packages.push(record);
    }
    // Fonts: the woff2 files, and @font-face rules under the families' plain names (as Google Fonts named them),
    // so the existing CSS (--f-display / --f-body / --f-mono) needs no change
    const css = ['/* Generated by scripts/vendor-web.js: the UI fonts, served by MetaCode itself (SIL Open Font License,',
      '   see /vendor/fonts/*.LICENSE). Variable fonts: one file per subset covers every weight. */'];
    for (const f of FONTS) {
      const pkg = pack(f.spec, tmp);
      const record = { name: f.spec.replace(/@[^@]+$/, ''), version: pkg.version, integrity: pkg.integrity, files: [] };
      const index = fs.readFileSync(path.join(pkg.root, 'index.css'), 'utf8');
      for (const subset of SUBSETS) {
        const name = f.file + '-' + subset + '-wght-normal.woff2';
        write(path.join('fonts', name), fs.readFileSync(path.join(pkg.root, 'files', name)), record);
        const block = index.split('@font-face').find(b => b.includes('/files/' + name + ')'));
        if (!block) throw new Error('No @font-face for ' + name + ' in ' + f.spec);
        const weight = (block.match(/font-weight:\s*([^;]+);/) || [])[1];
        const range = (block.match(/unicode-range:\s*([^;]+);/) || [])[1];
        css.push('@font-face {', "  font-family: '" + f.family + "';", '  font-style: normal;', '  font-display: swap;',
          '  font-weight: ' + weight + ';', "  src: url(../vendor/fonts/" + name + ") format('woff2-variations'), url(../vendor/fonts/" + name + ") format('woff2');",
          '  unicode-range: ' + range + ';', '}');
      }
      write(path.join('fonts', f.file + '.LICENSE'), fs.readFileSync(path.join(pkg.root, 'LICENSE')), record);
      manifest.packages.push(record);
    }
    fs.writeFileSync(FONTS_CSS, css.join('\n') + '\n');
    fs.writeFileSync(path.join(OUT, 'VENDOR.json'), JSON.stringify(manifest, null, 2) + '\n');
    const total = manifest.packages.reduce((n, p) => n + p.files.reduce((m, f) => m + f.bytes, 0), 0);
    console.log('public/vendor/: ' + manifest.packages.length + ' packages, ' + manifest.packages.reduce((n, p) => n + p.files.length, 0) +
      ' files, ' + Math.round(total / 1024) + ' KB; public/css/fonts.css written');
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

// Every file listed in VENDOR.json is there, unchanged
function check() {
  const manifest = JSON.parse(fs.readFileSync(path.join(OUT, 'VENDOR.json'), 'utf8'));
  const bad = [];
  for (const p of manifest.packages) {
    for (const f of p.files) {
      const file = path.join(ROOT, 'public', f.path);
      if (!fs.existsSync(file)) bad.push(f.path + ' is missing');
      else if (sha256(fs.readFileSync(file)) !== f.sha256) bad.push(f.path + ' changed');
    }
  }
  if (bad.length) { console.error(bad.join('\n')); process.exit(1); }
  console.log('public/vendor/ matches VENDOR.json');
}

if (require.main === module) {
  if (process.argv.includes('--check')) check(); else build();
}
module.exports = { PACKAGES, FONTS, check };
